rollback.sql:
CREATE TEMP TABLE v1_backfill_cycles AS
SELECT DISTINCT t.cycle_id FROM clinlims.eqa_cycle_state_transition t
WHERE t.trigger_event = 'V1_BACKFILL';

UPDATE clinlims.eqa_distribution d
SET cycle_id = NULL
WHERE d.cycle_id IN (SELECT cycle_id FROM v1_backfill_cycles);

DELETE FROM clinlims.eqa_cycle_state_transition t
WHERE t.cycle_id IN (SELECT cycle_id FROM v1_backfill_cycles);

DELETE FROM clinlims.eqa_cycle c
WHERE c.id IN (SELECT cycle_id FROM v1_backfill_cycles);

DROP TABLE v1_backfill_cycles;
